47: 
48:     }
49: 
50:     clearLocalFiles() {
51:         this.documentsList = [];
52:     }
53: 
54:     getUrlFile(base64:any, minetype:any) {
55:         return new Promise<string>((resolve, reject) => {
56:             const url = `data:${minetype};base64,${base64}`;
57:             fetch(url)
58:                 .then(res => res.blob())
59:                 .then(blob => {
60:                     const file = new File([blob], "File name", { type: minetype })
61:                     const url = URL.createObjectURL(file);
62:                     resolve(url);
63:                 })
64:         });
65:     }
66: 
67:     fileToBase64(file:any) {
68:         return new Promise((resolve, reject) => {
69:             const reader = new FileReader();
70:             reader.readAsDataURL(file);
71:             reader.onload = () => {
72:                 let encoded = reader.result!.toString().replace(/^data:(.*,)?/, '');
73:                 if ((encoded.length % 4) > 0) {
74:                     encoded += '='.repeat(4 - (encoded.length % 4));
75:                 }
76:                 resolve(encoded);
77:             };
78:             reader.onerror = error => reject(error);
79:         });
80:     }
81: 
82:     getManyFiles(query: string) {
83:         const documentsSubject = new Subject<any>();
84:         const documents$ = documentsSubject.asObservable();
85:         this.anyService.getp(environment.NUXEO_SERVICE, '/document'+query).subscribe(
